settings.customCss:
.mfp-easter-painted-garden{--mf-surface:#fbfdfd;--mf-ink:#204650;--mf-muted:#52696e;--mf-line:#a9c2c8;--mf-control:#ffffff;--mf-action:#a13e37;--mf-action-ink:#ffffff;--mf-focus:#237887;--mf-error:#a82c43;--mf-art:#daedf1;box-sizing:border-box;display:grid;grid-template-columns:minmax(0,0.9fr) minmax(0,1.7fr);gap:36px;align-items:center;padding:28px;width:100%;max-width:960px;margin:0 auto;border:0;border-radius:0;background:var(--mf-surface);color:var(--mf-ink);font-family:system-ui,-apple-system,"Segoe UI",sans-serif;font-size:16px;line-height:1.5;letter-spacing:0}
.mfp-easter-painted-garden *{box-sizing:border-box;min-width:0}
.mfp-easter-painted-garden .form-art{margin:0;position:relative;height:430px;overflow:hidden;border-radius:50% 50% 42% 42% / 33% 33% 24% 24%;background:var(--mf-art)}
.mfp-easter-painted-garden .form-art img{position:absolute;inset:0;display:block;width:100%;height:100%;object-fit:cover;object-position:50% center}
.mfp-easter-painted-garden .form-content{padding:0}
.mfp-easter-painted-garden .form-kicker{margin:0 0 8px;color:var(--mf-action);font-size:12px;font-weight:650}
.mfp-easter-painted-garden h2{margin:0 0 10px;font-family:Georgia,"Times New Roman",serif;font-size:32px;font-weight:400;line-height:1.15;overflow-wrap:anywhere}
.mfp-easter-painted-garden .form-heading p:last-child{margin:0;color:var(--mf-muted);font-size:14px}
.mfp-easter-painted-garden .form-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:17px 18px;margin-top:24px}
.mfp-easter-painted-garden .field-wide{grid-column:1 / -1}
.mfp-easter-painted-garden .field-slot{overflow-wrap:anywhere}
.mfp-easter-painted-garden .field-slot label{display:block;margin-bottom:7px;font-size:13px;font-weight:600;color:var(--mf-ink)}
.mfp-easter-painted-garden .field-slot small{display:block;margin-top:6px;font-size:12px;color:var(--mf-muted)}
.mfp-easter-painted-garden .field-slot input{display:block;width:100%;min-height:46px;padding:10px 12px;border:0;border-bottom:1px solid var(--mf-line);border-radius:0;background:var(--mf-control);color:var(--mf-ink);font:inherit;font-size:16px}
.mfp-easter-painted-garden .field-slot input:focus-visible{outline:3px solid var(--mf-focus);outline-offset:2px}
.mfp-easter-painted-garden .field-slot input::placeholder{color:var(--mf-muted);opacity:1}
.mfp-easter-painted-garden .field-slot select{display:block;width:100%;min-height:46px;padding:10px 12px;border:0;border-bottom:1px solid var(--mf-line);border-radius:0;background:var(--mf-control);color:var(--mf-ink);font:inherit;font-size:16px}
.mfp-easter-painted-garden .field-slot select:focus-visible{outline:3px solid var(--mf-focus);outline-offset:2px}
.mfp-easter-painted-garden .field-slot textarea{display:block;width:100%;min-height:82px;padding:10px 12px;border:0;border-bottom:1px solid var(--mf-line);border-radius:0;background:var(--mf-control);color:var(--mf-ink);font:inherit;font-size:16px;resize:vertical}
.mfp-easter-painted-garden .field-slot textarea:focus-visible{outline:3px solid var(--mf-focus);outline-offset:2px}
.mfp-easter-painted-garden .field-slot textarea::placeholder{color:var(--mf-muted);opacity:1}
.mfp-easter-painted-garden .form-actions{margin-top:24px}
.mfp-easter-painted-garden .form-actions button{display:flex;align-items:center;justify-content:space-between;gap:12px;width:100%;min-height:50px;padding:12px 18px;border:0;border-radius:3px;background:var(--mf-action);color:var(--mf-action-ink);font:inherit;font-size:14px;font-weight:600;cursor:pointer}
.mfp-easter-painted-garden .form-actions button span{font-size:20px}
.mfp-easter-painted-garden .form-actions button:hover{filter:brightness(1.1)}
.mfp-easter-painted-garden .form-actions button:focus-visible{outline:3px solid var(--mf-focus);outline-offset:3px}
.mfp-easter-painted-garden .form-actions button:disabled{opacity:.65;cursor:wait}
.mfp-easter-painted-garden .form-footer{margin-top:12px;color:var(--mf-muted);font-size:12px}
.mfp-easter-painted-garden .field-slot [aria-invalid="true"]{border-color:var(--mf-error)}
.mfp-easter-painted-garden .field-slot [role="alert"]{color:var(--mf-error);font-size:12px;margin:6px 0 0}
.mfp-easter-painted-garden [role="status"]{color:var(--mf-ink);overflow-wrap:anywhere}
@media(max-width:680px){.mfp-easter-painted-garden{grid-template-columns:1fr;gap:22px;padding:20px}.mfp-easter-painted-garden .form-art{height:160px;width:100%;max-width:360px;justify-self:center;border-radius:48% 48% 38% 38% / 32% 32% 26% 26%}.mfp-easter-painted-garden .form-art img{object-position:center 58%}.mfp-easter-painted-garden .form-content{padding:0}.mfp-easter-painted-garden h2{font-size:29px}.mfp-easter-painted-garden .form-fields{grid-template-columns:1fr;margin-top:20px}}
